{"content":"#!/usr/bin/env python3
"""Tomorrow Remembered — Final Rebuild Script (Part 2: Build PDF + EPUB + DOCX)
   FIXED: No cover art, historical sections restored, pencil sketch images embedded"""
import re, os, base64, shutil, zipfile
from pathlib import Path
from datetime import datetime

OUTPUT_DIR = Path("/home/bob/books/Tomorrow_Remembered/_resources/output")
ENHANCED_MD = OUTPUT_DIR / "Tomorrow_Remembered_Enhanced.md"

with open(ENHANCED_MD) as f:
    manuscript = f.read()

BOOK_TITLE = "Tomorrow Remembered"
BOOK_SUBTITLE = "Through the past the future is born unwritten"
AUTHOR = "Bob J Mills"
FILE_PREFIX = "Tomorrow_Remembered"

# ============================================================
# Parse TOC entries from manuscript
# ============================================================
toc_entries = []
lines = manuscript.split('\n')
for line in lines:
    s = line.strip()
    if re.match(r'^Part \w+:', s):
        toc_entries.append(('part', s))
    elif re.match(r'^Chapter \w+:', s):
        toc_entries.append(('chapter', s))

print(f"📋 TOC entries: {len(toc_entries)}")
for t, title in toc_entries:
    print(f"  [{t}] {title[:60]}")

# ============================================================
# Convert markdown to HTML
# ============================================================
def esc(text):
    return text.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')

def inline_md(text):
    text = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', text)
    text = re.sub(r'\*(.+?)\*', r'<em>\1</em>', text)
    return text

def md_to_html(text):
    lines = text.split('\n')
    result = []; in_ul = False; in_quote = False; in_code = False

    def close_containers():
        nonlocal in_ul, in_quote
        out = []
        if in_ul: out.append('</ul>'); in_ul = False
        if in_quote: out.append('</blockquote>'); in_quote = False
        return out

    for raw in lines:
        s = raw.strip()
        if not s:
            result.extend(close_containers()); result.append(''); continue
        if s in ('---', '___', '***'):
            result.extend(close_containers()); result.append('<hr>'); continue
        # Image handling: ![alt](path)
        img_match = re.match(r'^!\[(.+?)\]\((.+?)\)$', s)
        if img_match:
            result.extend(close_containers())
            alt = esc(img_match.group(1))
            src = img_match.group(2)
            result.append(f'<div class="part-image"><img src="{src}" alt="{alt}"></div>')
            continue
        if re.match(r'^Part \w+:', s):
            result.extend(close_containers())
            result.append(f'<h2 class="part-title">{esc(s)}</h2>'); continue
        if re.match(r'^Chapter \w+:', s):
            result.extend(close_containers())
            result.append(f'<h3>{esc(s)}</h3>'); continue
        if s.startswith('## '):
            result.extend(close_containers())
            result.append(f'<h4>{esc(s[3:])}</h4>'); continue
        if s.startswith('### '):
            result.extend(close_containers())
            result.append(f'<h5>{esc(s[4:])}</h5>'); continue
        if s.startswith('>'):
            if in_ul: result.extend(close_containers())
            if not in_quote: result.append('<blockquote>'); in_quote = True
            result.append(f'<p>{inline_md(s[1:].strip())}</p>'); continue
        if re.match(r'^\*\*.+\*\*$', s) and len(s) < 80:
            result.extend(close_containers())
            result.append(f'<p class="section-heading">{inline_md(s)}</p>'); continue
        result.extend(close_containers())
        result.append(f'<p>{inline_md(s)}</p>')
    result.extend(close_containers())
    return '\n'.join(result)

body_html = md_to_html(manuscript)
print(f"HTML body generated: {len(body_html):,} chars")

# ============================================================
# Add TOC anchor IDs
# ============================================================
anchor_map = {}
for idx, (ttype, title) in enumerate(toc_entries):
    anchor_id = f"toc-{idx}"
    anchor_map[title] = anchor_id

for title, anchor_id in anchor_map.items():
    safe_title = esc(title)
    if 'Part ' in title:
        old = f'<h2 class="part-title">{safe_title}</h2>'
        new = f'<h2 class="part-title" id="{anchor_id}">{safe_title}</h2>'
    elif 'Chapter ' in title:
        old = f'<h3>{safe_title}</h3>'
        new = f'<h3 id="{anchor_id}">{safe_title}</h3>'
    else:
        continue
    count = body_html.count(old)
    if count == 0:
        print(f"  ⚠️ Anchor NOT found: {title[:60]}")
    body_html = body_html.replace(old, new, 1)

anchor_count = body_html.count('id="toc-')
print(f"📌 Anchors assigned: {anchor_count}/{len(toc_entries)}")

# ============================================================
# Part Images: Encode as base64 for PDF embedding
# ============================================================
part_images_base64 = {}
part_imgs = [
    ("part1_ignition.jpg", "Part One: The Ignition"),
    ("part2_building.jpg", "Part Two: The Building"),
    ("part3_particle.jpg", "Part Three: The Particle and The Person"),
    ("part4_forward.jpg", "Part Four: Building Forward"),
    ("part5_future.jpg", "Part Five: The Futures Beyond"),
]
for img_file, part_title in part_imgs:
    img_path = OUTPUT_DIR / f"part_images/{img_file}"
